{
  "core_question": "How should a 5,000-employee self-insured employer evaluate the clinical justification, legal compliance, and financial impact of covering GLP‑1 medications for obesity rather than only for type 2 diabetes, and what utilization-management criteria should be applied?",
  "rationale": "The decision involves medical evidence and patient selection (healthcare), ERISA/state law and anti-discrimination issues (legal), and cost/ROI analysis for a large self-insured plan (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What clinical evidence supports covering GLP‑1 agents such as semaglutide and tirzepatide for obesity in a self-insured employer plan, and what utilization-management criteria (e.g., BMI thresholds, prior therapy requirements, monitoring protocols) should be implemented to ensure appropriate use?",
    "legal": "Under ERISA and applicable state insurance laws, what legal considerations must the employer address when adding GLP‑1 medications for obesity to its self-insured benefit plan, including mandatory coverage provisions, anti-discrimination obligations, and any regulatory reporting requirements?",
    "finance": "What are the projected financial impacts—drug acquisition costs, potential savings from weight loss-related health improvements, utilization-management expenses, and overall ROI—for a 5,000-employee self-insured employer that chooses to cover GLP‑1 agents for obesity?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Recent drug pricing changes, rebate structures, evolving clinical guidelines for obesity use of GLP‑1s, and any new ERISA or state law updates post-2024 may affect the accuracy of the analysis."
}
